/**
 * Single place where ECharts features are registered.
 *
 * Always import from `echarts/core` and register explicitly — `import * as
 * echarts from 'echarts'` pulls every chart type and renderer (~1 MB extra),
 * and an app bundle ships as a `ui://` protocol resource, so raw size travels.
 *
 * ECharts' core dominates the cost, so each additional chart type after the
 * first is comparatively cheap. Views that need no chart engine — Stat, Bullet,
 * Table — are plain DOM and stay out of this bundle entirely.
 */

import * as echarts from 'echarts/core';
import { BarChart, HeatmapChart, LineChart } from 'echarts/charts';
import {
  BrushComponent,
  DataZoomComponent,
  GridComponent,
  LegendComponent,
  MarkLineComponent,
  TooltipComponent,
  VisualMapComponent,
} from 'echarts/components';
import { CanvasRenderer } from 'echarts/renderers';

echarts.use([
  LineChart,
  BarChart,
  HeatmapChart,
  GridComponent,
  TooltipComponent,
  DataZoomComponent,
  LegendComponent,
  MarkLineComponent,
  // Brush drives "select a window and ask the agent"; dataZoom alone cannot,
  // because a drag there pans or zooms rather than reporting a range.
  BrushComponent,
  // The heatmap's colour scale.
  VisualMapComponent,
  CanvasRenderer,
]);

export { echarts };
export type EChartsOption = Parameters<echarts.ECharts['setOption']>[0];

package mcpgrafana

import (
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// okHandler is the inner handler the middleware wraps. We assert that the
// middleware either calls it (allow) or short-circuits before it (deny).
func okHandler(t *testing.T) (http.Handler, *bool) {
	t.Helper()
	called := false
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		called = true
		w.WriteHeader(http.StatusOK)
	}), &called
}

func TestDNSRebindingProtectionMiddleware_Host(t *testing.T) {
	cases := []struct {
		name       string
		allowed    []string
		host       string
		wantStatus int
		wantCalled bool
	}{
		{"matching host passes", []string{"localhost:8000"}, "localhost:8000", http.StatusOK, true},
		{"case-insensitive host match passes", []string{"localhost:8000"}, "LOCALHOST:8000", http.StatusOK, true},
		{"mismatched host blocked", []string{"localhost:8000"}, "evil.example:8000", http.StatusForbidden, false},
		{"loopback IP variant blocked when not allowlisted", []string{"localhost:8000"}, "127.0.0.1:8000", http.StatusForbidden, false},
		{"empty allowlist permits everything (Host check disabled)", nil, "anything.example", http.StatusOK, true},
		{"wildcard disables host validation", []string{"*"}, "rebinding.attacker.example", http.StatusOK, true},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			inner, called := okHandler(t)
			mw := DNSRebindingProtectionMiddleware(HostOriginPolicy{AllowedHosts: tc.allowed})

			req := httptest.NewRequest(http.MethodGet, "/sse", nil)
			req.Host = tc.host
			rr := httptest.NewRecorder()
			mw(inner).ServeHTTP(rr, req)

			assert.Equal(t, tc.wantStatus, rr.Code)
			assert.Equal(t, tc.wantCalled, *called)
		})
	}
}

func TestDNSRebindingProtectionMiddleware_Origin(t *testing.T) {
	cases := []struct {
		name       string
		allowed    []string
		origin     string
		wantStatus int
		wantCalled bool
	}{
		{"no Origin header passes (CLI client)", nil, "", http.StatusOK, true},
		{"empty allowlist rejects any Origin", nil, "http://evil.example", http.StatusForbidden, false},
		{"matching Origin passes", []string{"http://localhost:3000"}, "http://localhost:3000", http.StatusOK, true},
		{"case-insensitive Origin match passes", []string{"http://localhost:3000"}, "HTTP://LOCALHOST:3000", http.StatusOK, true},
		{"non-matching Origin blocked", []string{"http://localhost:3000"}, "http://evil.example", http.StatusForbidden, false},
		{"wildcard disables Origin validation even with Origin present", []string{"*"}, "http://evil.example", http.StatusOK, true},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			inner, called := okHandler(t)
			// AllowedHosts is left empty so only Origin is exercised here.
			mw := DNSRebindingProtectionMiddleware(HostOriginPolicy{AllowedOrigins: tc.allowed})

			req := httptest.NewRequest(http.MethodGet, "/sse", nil)
			if tc.origin != "" {
				req.Header.Set("Origin", tc.origin)
			}
			rr := httptest.NewRecorder()
			mw(inner).ServeHTTP(rr, req)

			assert.Equal(t, tc.wantStatus, rr.Code)
			assert.Equal(t, tc.wantCalled, *called)
		})
	}
}

// TestDNSRebindingProtectionMiddleware_RebindingScenario simulates the exact
// DNS-rebinding case from the customer report: a browser hits 127.0.0.1:8000
// but the URL bar (and therefore the Host header) is the attacker's domain.
// With the default Host allowlist derived from the bind address, the request
// must be rejected before reaching the SSE handler.
func TestDNSRebindingProtectionMiddleware_RebindingScenario(t *testing.T) {
	inner, called := okHandler(t)
	policy := HostOriginPolicy{AllowedHosts: DefaultAllowedHosts("localhost:8000")}
	mw := DNSRebindingProtectionMiddleware(policy)

	req := httptest.NewRequest(http.MethodGet, "/sse", nil)
	req.Host = "rebinding.attacker.example:8000"
	req.Header.Set("Origin", "http://rebinding.attacker.example:8000")

	rr := httptest.NewRecorder()
	mw(inner).ServeHTTP(rr, req)

	assert.Equal(t, http.StatusForbidden, rr.Code)
	assert.False(t, *called, "inner handler must not be reached for a rebinding Host")
}

func TestDefaultAllowedHosts(t *testing.T) {
	cases := []struct {
		name    string
		address string
		want    []string
	}{
		{
			name:    "localhost bind allows IPv4 and IPv6 loopback too",
			address: "localhost:8000",
			want:    []string{"localhost:8000", "127.0.0.1:8000", "[::1]:8000"},
		},
		{
			name:    "wildcard IPv4 bind allows all loopback variants",
			address: "0.0.0.0:8000",
			want:    []string{"localhost:8000", "127.0.0.1:8000", "[::1]:8000"},
		},
		{
			name:    "empty host bind allows all loopback variants",
			address: ":8000",
			want:    []string{"localhost:8000", "127.0.0.1:8000", "[::1]:8000"},
		},
		{
			name:    "explicit hostname binds only that hostname",
			address: "mcp.internal:8000",
			want:    []string{"mcp.internal:8000"},
		},
		{
			name:    "explicit IPv4 binds only that IPv4",
			address: "10.0.0.5:8000",
			want:    []string{"10.0.0.5:8000"},
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			got := DefaultAllowedHosts(tc.address)
			require.Equal(t, tc.want, got)
		})
	}
}

package mcpgrafana

import (
	"bytes"
	"context"
	"errors"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"testing"
	"time"

	"github.com/modelcontextprotocol/go-sdk/mcp"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

const testCallerToken = "[REDACTED]"

const initializeBody = `{"jsonrpc":"2.0","id":0,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"test","version":"0"}}}`

func TestCallerAuth_StreamableHTTP_EndToEnd(t *testing.T) {
	mcpServer := mcp.NewServer(&mcp.Implementation{Name: "test", Version: "0"}, nil)
	handler := mcp.NewStreamableHTTPHandler(func(*http.Request) *mcp.Server { return mcpServer }, &mcp.StreamableHTTPOptions{
		Stateless: true,
	})

	mux := http.NewServeMux()
	mux.Handle("/mcp", RequireBearerToken(testCallerToken, slog.Default())(handler))
	ts := httptest.NewServer(mux)
	t.Cleanup(ts.Close)

	post := func(t *testing.T, authHeader, sessionID string) *http.Response {
		t.Helper()
		req, err := http.NewRequest(http.MethodPost, ts.URL+"/mcp", bytes.NewBufferString(initializeBody))
		require.NoError(t, err)
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Accept", "application/json, text/event-stream")
		if authHeader != "" {
			req.Header.Set("Authorization", authHeader)
		}
		if sessionID != "" {
			req.Header.Set("Mcp-Session-Id", sessionID)
		}
		resp, err := http.DefaultClient.Do(req)
		require.NoError(t, err)
		t.Cleanup(func() { _ = resp.Body.Close() })
		return resp
	}

	t.Run("no token cannot call tools -> 401", func(t *testing.T) {
		resp := post(t, "", "")
		assert.Equal(t, http.StatusUnauthorized, resp.StatusCode)
	})

	t.Run("wrong token -> 401", func(t *testing.T) {
		resp := post(t, "Bearer nope", "")
		assert.Equal(t, http.StatusUnauthorized, resp.StatusCode)
	})

	t.Run("self-minted session id does not bypass auth -> 401", func(t *testing.T) {
		resp := post(t, "", "made-up-session-id")
		assert.Equal(t, http.StatusUnauthorized, resp.StatusCode)
	})

	t.Run("valid token initializes (not 401)", func(t *testing.T) {
		resp := post(t, "Bearer "+testCallerToken, "")
		assert.NotEqual(t, http.StatusUnauthorized, resp.StatusCode)
	})

	t.Run("OPTIONS preflight passes without a token", func(t *testing.T) {
		req, err := http.NewRequest(http.MethodOptions, ts.URL+"/mcp", nil)
		require.NoError(t, err)
		resp, err := http.DefaultClient.Do(req)
		require.NoError(t, err)
		t.Cleanup(func() { _ = resp.Body.Close() })
		assert.NotEqual(t, http.StatusUnauthorized, resp.StatusCode)
	})
}

func TestCallerAuth_SSE_EndToEnd(t *testing.T) {
	mcpServer := mcp.NewServer(&mcp.Implementation{Name: "test", Version: "0"}, nil)
	sse := mcp.NewSSEHandler(func(*http.Request) *mcp.Server { return mcpServer }, nil)
	ts := httptest.NewServer(RequireBearerToken(testCallerToken, slog.Default())(sse))
	t.Cleanup(ts.Close)

	get := func(t *testing.T, authHeader string) (*http.Response, error) {
		t.Helper()
		ctx, cancel := context.WithTimeout(context.Background(), 500*time.Millisecond)
		t.Cleanup(cancel)
		req, err := http.NewRequestWithContext(ctx, http.MethodGet, ts.URL+"/sse", nil)
		require.NoError(t, err)
		if authHeader != "" {
			req.Header.Set("Authorization", authHeader)
		}
		return http.DefaultClient.Do(req)
	}

	t.Run("no token -> 401", func(t *testing.T) {
		resp, err := get(t, "")
		require.NoError(t, err)
		t.Cleanup(func() { _ = resp.Body.Close() })
		assert.Equal(t, http.StatusUnauthorized, resp.StatusCode)
	})

	t.Run("valid token opens the stream (not 401)", func(t *testing.T) {
		resp, err := get(t, "Bearer "+testCallerToken)
		if err != nil && !errors.Is(err, context.DeadlineExceeded) {
			require.NoError(t, err)
		}
		require.NotNil(t, resp)
		t.Cleanup(func() { _ = resp.Body.Close() })
		assert.Equal(t, http.StatusOK, resp.StatusCode)
	})
}

package mcpgrafana

import (
	"bytes"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

func TestRequireBearerToken(t *testing.T) {
	const token = "[REDACTED]"

	// Downstream handler records whether it was reached.
	var reached bool
	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		reached = true
		w.WriteHeader(http.StatusOK)
	})
	handler := RequireBearerToken(token, slog.Default())(next)

	cases := []struct {
		name       string
		authHeader string
		wantStatus int
		wantReach  bool
	}{
		{"missing header", "", http.StatusUnauthorized, false},
		{"wrong token", "Bearer wrong", http.StatusUnauthorized, false},
		{"not bearer scheme", "Basic " + token, http.StatusUnauthorized, false},
		{"empty bearer", "Bearer ", http.StatusUnauthorized, false},
		{"valid token", "Bearer " + token, http.StatusOK, true},
		{"valid token lowercase scheme", "bearer " + token, http.StatusOK, true},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			reached = false
			req := httptest.NewRequest(http.MethodPost, "/mcp", nil)
			if tc.authHeader != "" {
				req.Header.Set("Authorization", tc.authHeader)
			}
			rec := httptest.NewRecorder()
			handler.ServeHTTP(rec, req)

			assert.Equal(t, tc.wantStatus, rec.Code)
			assert.Equal(t, tc.wantReach, reached)
			if tc.wantStatus == http.StatusUnauthorized {
				assert.Equal(t, "Bearer", rec.Header().Get("WWW-Authenticate"))
			}
		})
	}
}

// An accidentally-empty expected token must fail closed, never allow-all.
func TestRequireBearerToken_EmptyExpectedFailsClosed(t *testing.T) {
	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		t.Fatal("handler should not be reached when expected token is empty")
	})
	handler := RequireBearerToken("", slog.Default())(next)

	req := httptest.NewRequest(http.MethodPost, "/mcp", nil)
	req.Header.Set("Authorization", "Bearer anything")
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)

	require.Equal(t, http.StatusUnauthorized, rec.Code)
}

// Rejections must be logged for audit, but the token value must never appear in
// the logs.
func TestRequireBearerToken_LogsRejectionWithoutLeakingToken(t *testing.T) {
	const secret = "[REDACTED]"
	const presented = "the-wrong-presented-token"

	var buf bytes.Buffer
	logger := slog.New(slog.NewTextHandler(&buf, &slog.HandlerOptions{Level: slog.LevelWarn}))

	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		t.Fatal("handler should not be reached for a rejected request")
	})
	handler := RequireBearerToken(secret, logger)(next)

	req := httptest.NewRequest(http.MethodPost, "/mcp", nil)
	req.Header.Set("Authorization", "Bearer "+presented)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)

	require.Equal(t, http.StatusUnauthorized, rec.Code)

	logs := buf.String()
	assert.Contains(t, logs, "Rejected unauthenticated request")
	assert.Contains(t, logs, "invalid bearer token")
	assert.Contains(t, logs, "method=POST")
	assert.Contains(t, logs, "path=/mcp")
	// The secret and the presented token must never be written to logs.
	assert.NotContains(t, logs, secret)
	assert.NotContains(t, logs, presented)
}

// A successful (authenticated) request must not emit a rejection log line.
func TestRequireBearerToken_NoLogOnSuccess(t *testing.T) {
	const secret = "[REDACTED]"

	var buf bytes.Buffer
	logger := slog.New(slog.NewTextHandler(&buf, &slog.HandlerOptions{Level: slog.LevelWarn}))

	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
	})
	handler := RequireBearerToken(secret, logger)(next)

	req := httptest.NewRequest(http.MethodPost, "/mcp", nil)
	req.Header.Set("Authorization", "Bearer "+secret)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)

	require.Equal(t, http.StatusOK, rec.Code)
	assert.Empty(t, buf.String(), "authenticated request should not log a rejection")
}

// After successful authentication the caller's Authorization header must be
// stripped so it can never be forwarded to Grafana or folded into a cache key.
func TestRequireBearerToken_StripsAuthorizationAfterAuth(t *testing.T) {
	const token = "[REDACTED]"

	var seenAuth string
	var reached bool
	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		reached = true
		seenAuth = r.Header.Get("Authorization")
		w.WriteHeader(http.StatusOK)
	})
	handler := RequireBearerToken(token, slog.Default())(next)

	req := httptest.NewRequest(http.MethodPost, "/mcp", nil)
	req.Header.Set("Authorization", "Bearer "+token)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)

	require.Equal(t, http.StatusOK, rec.Code)
	require.True(t, reached)
	assert.Empty(t, seenAuth, "Authorization header must be stripped before reaching the downstream handler")
}

// CORS preflight must be allowed through unauthenticated so browser clients can
// negotiate; it carries no bearer token and performs no MCP operation.
func TestRequireBearerToken_AllowsOPTIONSPreflight(t *testing.T) {
	const token = "[REDACTED]"

	var reached bool
	next := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		reached = true
		w.WriteHeader(http.StatusNoContent)
	})
	handler := RequireBearerToken(token, slog.Default())(next)

	req := httptest.NewRequest(http.MethodOptions, "/mcp", nil)
	rec := httptest.NewRecorder()
	handler.ServeHTTP(rec, req)

	assert.True(t, reached, "OPTIONS preflight should reach the downstream CORS handler")
	assert.Equal(t, http.StatusNoContent, rec.Code)
}

func TestForwardsAuthorizationHeader(t *testing.T) {
	cases := []struct {
		name string
		env  string
		want bool
	}{
		{"unset -> false", "", false},
		{"unrelated headers -> false", "Cookie, X-Session-Id", false},
		{"exact match -> true", "Authorization", true},
		{"case-insensitive match -> true", " cookie , authorization ", true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			t.Setenv("GRAFANA_FORWARD_HEADERS", tc.env)
			assert.Equal(t, tc.want, ForwardsAuthorizationHeader())
		})
	}
}

func TestIsLoopbackOnlyBind(t *testing.T) {
	cases := []struct {
		address string
		want    bool
	}{
		{"localhost:8000", true},
		{"127.0.0.1:8000", true},
		{"[::1]:8000", true},
		{"foo.localhost:8000", true},
		{"127.0.0.1", true},
		{"::1", true},
		// Public / wildcard binds.
		{"0.0.0.0:8000", false},
		{":8000", false},
		{"[::]:8000", false},
		{"192.168.1.10:8000", false},
		{"10.0.0.5:8000", false},
		{"example.com:8000", false},
		{"grafana.example.com:8000", false},
	}
	for _, tc := range cases {
		t.Run(tc.address, func(t *testing.T) {
			assert.Equal(t, tc.want, IsLoopbackOnlyBind(tc.address))
		})
	}
}
